package claybin

import (
	"fmt"
	"os"

	"kilnbench/hopsrc/vat"
)

const (
	src     = "/app/vats/plaster.vat"
	dst     = "/app/vats/worker.vat"
	migDir  = "/app/inkstack/migrations"
	okPath  = "/app/vats/assay.ok"
)

func EmitWorker() error {
	// A previous successful assay must never survive a failed spill.
	if err := os.Remove(okPath); err != nil && !os.IsNotExist(err) {
		return err
	}

	st, err := vat.Parse(src)
	if err != nil {
		return err
	}
	head, err := vat.LedgerHead(migDir)
	if err != nil {
		return err
	}
	if st.LastApplied() != head {
		return fmt.Errorf("source schema_version=%s, ledger head=%s", st.LastApplied(), head)
	}
	return vat.CopyFile(src, dst)
}
EOF
