package scorepit

import (
	"fmt"
	"os"

	"kilnbench/hopsrc/vat"
)

const (
	worker = "/app/vats/worker.vat"
	okPath = "/app/vats/assay.ok"
	migDir = "/app/inkstack/migrations"
)

func ScoreWorker() int {
	// Never allow a marker from an earlier run to represent this assay.
	if err := os.Remove(okPath); err != nil && !os.IsNotExist(err) {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	st, err := vat.Parse(worker)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	version := st.LastApplied()
	fmt.Printf("schema_version=%s\n", version)

	head, err := vat.LedgerHead(migDir)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if version != head {
		fmt.Fprintf(os.Stderr, "schema_version %s lags ledger head %s\n", version, head)
		return 1
	}
	if !st.HasCol("attempt_slot") {
		fmt.Fprintln(os.Stderr, "unknown-column: attempt_slot")
		return 1
	}
	if err := os.WriteFile(okPath, []byte("ok\n"), 0644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	return 0
}
EOF
